export function findKnowledgeHints({ relativePath='', selector='', lineText='', surface='' }) {
  const haystack = `${relativePath} ${selector} ${lineText} ${surface}`;
  const hints = [];
  for (const hint of SELECTOR_HINTS) {
    if (hint.pattern.test(haystack)) hints.push(hint);
    if (hints.length >= 6) break;
  }
  const rules = REPAIR_RULES.filter((r)=> surface && r.surface.toLowerCase()===String(surface).toLowerCase()).slice(0,6);
  return { hints, rules };
}
export function buildGenericRepairSteps(finding) {
  const selector = finding.cssContext?.selector || finding.selectorHint || 'nearest owner selector';
  return [
    `Open ${finding.relativePath} around line ${finding.line}.`,
    `Identify the declaration using a priority override token inside ${selector}.`,
    'Search the file for the same selector and related state selectors.',
    'Pick the canonical owner block: usually the first semantic block or component-bound block.',
    'Move the intended property and value there without force.',
    'Remove any duplicate late override block made only to win cascade.',
    'If the target is a pseudo-layer, fix the pseudo-layer owner rather than hiding it.',
    'Run the gate again with explain output.'
  ];
}
